// Headless verification harness for game.html (temporary; not part of the deliverable)
const fs = require('fs');
const html = fs.readFileSync('/home/zmhel/gitrepos/learn-ai/eval01/runs/.gen-work/t34/game.html', 'utf8');
const blocks = [...html.matchAll(/<script>([\s\S]*?)<\/script>/g)].map(m => m[1]);
console.log('script blocks:', blocks.length, 'chars:', blocks[0].length);
const src = blocks[0];

// no document -> boot() will not run
const sandbox = {};
const fn = new Function(src + '\n;return {runTests, runBench, newGame, greedyStep, stateHash, score, S, TREE, builtTiles, avgMorale, endTurn, saveString, loadString, caps, RES};');
const api = fn();

const res = api.runTests();
let pass = 0;
res.forEach((r, i) => {
  if (r.pass) pass++;
  console.log((r.pass ? 'PASS' : 'FAIL') + '  ' + String(i + 1).padStart(2, '0') + '. ' + r.name);
  if (r.detail) console.log('        ' + r.detail);
});
console.log('\n' + pass + '/' + res.length + ' assertions passed');

console.log('\n--- benchmark determinism (200 turns, seed 1337) ---');
const t0 = Date.now();
const b1 = api.runBench(1337, 200);
const b2 = api.runBench(1337, 200);
console.log('hash1', b1.hash, 'hash2', b2.hash, 'match:', b1.hash === b2.hash, 'ms:', Date.now() - t0);
console.log('pop', b1.pop, 'research', b1.research, 'buildings', b1.buildings, 'morale', b1.morale,
            'storms', b1.storms, 'events', b1.events, 'trades', b1.trades, 'score', b1.score);
console.log('at turn 60:', JSON.stringify(b1.at60));

console.log('\n--- greedy outcomes across seeds (60 turns, interactive rules) ---');
for (const seed of [1337, 7, 2024, 99, 555]) {
  const S = api.newGame(seed);
  S.bench = true;
  for (let i = 0; i < 60; i++) api.greedyStep(S);
  console.log('seed', seed, '-> outcome', S.outcome, 'pop', S.people.length,
              'research', Object.keys(S.done).length, 'morale', api.avgMorale(S).toFixed(1),
              'food', S.res.food.toFixed(0), 'water', S.res.water.toFixed(0),
              'score', api.score(S).total);
}

console.log('\n--- do-nothing player (never assign/build) ---');
{
  const S = api.newGame(1337);
  S.bench = true;
  for (let i = 0; i < 60 && S.people.length > 0; i++) api.endTurn(S);
  console.log('outcome', S.outcome, 'pop', S.people.length, 'turn', S.turn);
}

